const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>DaySpan \u2014 Date Duration Calculator: Days Between Dates</title>\n<meta name=\"description\" content=\"DaySpan is a free date duration calculator. Count exact days between two dates with weekend counts, leap days in the span, day-of-week callouts, milestone mode (10,000 days old), and an add/subtract days tool \u2014 instantly, in your browser.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script>\ntailwind.config = {\n  theme: {\n    extend: {\n      colors: { cream: '#FDF6EC', terra: '#C2410C', ink: '#334155', gold: '#D97706', parch: '#F8EEDC', linec: '#EAD9BE' },\n      fontFamily: { display: ['Fraunces', 'Georgia', 'serif'], body: ['Inter', 'system-ui', 'sans-serif'] }\n    }\n  }\n};\n</script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600;9..144,800;9..144,900&family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  body { font-family: 'Inter', system-ui, sans-serif; }\n  .font-display { font-family: 'Fraunces', Georgia, serif; }\n  /* ---- ticket-style result cards: perforated middle with notches ---- */\n  .ticket { position: relative; background: #fff; border: 1px solid #EAD9BE; border-radius: 14px; box-shadow: 0 2px 6px rgba(194,65,12,.06); }\n  .ticket::before, .ticket::after { content: \"\"; position: absolute; top: 56%; width: 22px; height: 22px; background: #FDF6EC; border: 1px solid #EAD9BE; border-radius: 9999px; transform: translateY(-50%); z-index: 2; }\n  .ticket::before { left: -12px; }\n  .ticket::after { right: -12px; }\n  .ticket .percline { position: absolute; top: 56%; left: 14px; right: 14px; border-top: 2px dashed #EAD9BE; z-index: 1; }\n  .ticket-top { position: relative; z-index: 0; }\n  .ticket-bottom { position: relative; z-index: 0; }\n  /* ---- desk-calendar page cards ---- */\n  .calpage { background: #fff; border: 1px solid #EAD9BE; border-radius: 14px; overflow: hidden; box-shadow: 0 4px 12px rgba(194,65,12,.08); }\n  .calpage .cap { background: #C2410C; color: #fff; }\n  .rings { display: flex; gap: 14px; justify-content: center; margin-top: -7px; position: relative; z-index: 3; }\n  .rings span { width: 10px; height: 10px; border-radius: 9999px; background: #D97706; border: 2px solid #fff; box-shadow: 0 1px 2px rgba(0,0,0,.2); }\n  input[type=\"date\"], input[type=\"time\"], input[type=\"number\"], input[type=\"text\"] { color-scheme: light; }\n  input[type=\"date\"]:focus, input[type=\"time\"]:focus, input[type=\"number\"]:focus { outline: 2px solid #C2410C; outline-offset: 1px; }\n  .tabbtn[aria-selected=\"true\"] { background: #C2410C; color: #fff; }\n  .tabbtn[aria-selected=\"false\"] { background: #fff; color: #334155; }\n  .tabbtn[aria-selected=\"false\"]:hover { background: #F8EEDC; }\n  details.faq-item summary::-webkit-details-marker { display: none; }\n  details.faq-item[open] .faq-chev { transform: rotate(180deg); }\n  .faq-chev { transition: transform .2s ease; }\n  .paperbg { background-image: radial-gradient(#EAD9BE 1px, transparent 1px); background-size: 22px 22px; }\n  .no-print {} \n  @media print { .no-print { display: none !important; } }\n</style>\n</head>\n<body id=\"top\" class=\"bg-cream text-ink font-body antialiased\">\n\n<!-- ================= STICKY HEADER ================= -->\n<header class=\"sticky top-0 z-40 bg-cream/95 backdrop-blur border-b border-linec\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"flex items-center gap-2.5\" aria-label=\"DaySpan home\">\n      <svg width=\"30\" height=\"30\" viewBox=\"0 0 32 32\" fill=\"none\" aria-hidden=\"true\">\n        <rect x=\"3\" y=\"6\" width=\"26\" height=\"23\" rx=\"3\" fill=\"#C2410C\"/>\n        <rect x=\"3\" y=\"6\" width=\"26\" height=\"8\" rx=\"3\" fill=\"#9A3412\"/>\n        <rect x=\"8\" y=\"3\" width=\"3\" height=\"7\" rx=\"1.5\" fill=\"#334155\"/>\n        <rect x=\"21\" y=\"3\" width=\"3\" height=\"7\" rx=\"1.5\" fill=\"#334155\"/>\n        <circle cx=\"11\" cy=\"19\" r=\"2.2\" fill=\"#FDF6EC\"/>\n        <circle cx=\"16.5\" cy=\"19\" r=\"2.2\" fill=\"#FDF6EC\"/>\n        <circle cx=\"22\" cy=\"19\" r=\"2.2\" fill=\"#FDF6EC\"/>\n        <circle cx=\"11\" cy=\"24.5\" r=\"2.2\" fill=\"#FDF6EC\"/>\n        <circle cx=\"16.5\" cy=\"24.5\" r=\"2.2\" fill=\"#D97706\"/>\n      </svg>\n      <span class=\"font-display font-extrabold text-2xl tracking-tight text-terra\">DaySpan</span>\n    </a>\n    <nav class=\"flex items-center gap-5 text-sm font-semibold\" aria-label=\"Main navigation\">\n      <a href=\"#top\" class=\"text-ink hover:text-terra transition-colors\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"text-ink hover:text-terra transition-colors\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ================= TOP AD ================= -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ================= TOOL ================= -->\n<main class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8\">\n  <div class=\"text-center max-w-2xl mx-auto\">\n    <span class=\"inline-flex items-center gap-1.5 bg-gold/15 text-gold border border-gold/40 rounded-full px-4 py-1.5 text-xs font-bold uppercase tracking-wider\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" aria-hidden=\"true\"><path d=\"M20 6L9 17l-5-5\"/></svg>\n      Unlimited Free Usage\n    </span>\n    <h1 class=\"font-display font-black text-4xl sm:text-5xl text-ink mt-4 leading-tight\">How many days<br class=\"sm:hidden\"> between <span class=\"text-terra\">two dates?</span></h1>\n    <p class=\"text-ink/70 mt-3 text-base sm:text-lg\">Exact day counts with weekend tallies, leap days, day-of-week callouts, milestone birthdays and a quick date jumper \u2014 calculated instantly as you type.</p>\n  </div>\n\n  <!-- Tabs -->\n  <div class=\"flex justify-center mt-7 no-print\" role=\"tablist\" aria-label=\"Calculator modes\">\n    <div class=\"inline-flex bg-parch border border-linec rounded-full p-1 gap-1\">\n      <button id=\"tab-duration\" role=\"tab\" aria-selected=\"true\" class=\"tabbtn rounded-full px-4 sm:px-6 py-2 text-sm font-bold transition-colors\" data-tab=\"duration\">Duration</button>\n      <button id=\"tab-milestone\" role=\"tab\" aria-selected=\"false\" class=\"tabbtn rounded-full px-4 sm:px-6 py-2 text-sm font-bold transition-colors\" data-tab=\"milestone\">Milestones</button>\n      <button id=\"tab-jumper\" role=\"tab\" aria-selected=\"false\" class=\"tabbtn rounded-full px-4 sm:px-6 py-2 text-sm font-bold transition-colors\" data-tab=\"jumper\">Date Jumper</button>\n    </div>\n  </div>\n\n  <!-- ============ PANEL: DURATION ============ -->\n  <section id=\"panel-duration\" role=\"tabpanel\" aria-labelledby=\"tab-duration\" class=\"mt-6\">\n    <div class=\"grid md:grid-cols-[1fr_auto_1fr] gap-4 items-stretch max-w-4xl mx-auto\">\n      <!-- Start date card -->\n      <div class=\"calpage\">\n        <div class=\"cap text-center py-1.5\">\n          <div id=\"startCap\" class=\"text-[11px] font-extrabold tracking-[0.2em] uppercase\">Start month</div>\n        </div>\n        <div class=\"rings\" aria-hidden=\"true\"><span></span><span></span></div>\n        <div class=\"text-center px-4 pt-1 pb-3\">\n          <div id=\"startBig\" class=\"font-display font-black text-6xl text-ink leading-none\">\u2013</div>\n          <div id=\"startDow\" class=\"text-sm font-semibold text-terra mt-1\">Pick a start date</div>\n          <input id=\"dateStart\" type=\"date\" aria-label=\"Start date\" class=\"mt-3 w-full border border-linec rounded-lg px-3 py-2 text-sm bg-cream focus:border-terra\">\n          <div id=\"startLeap\" class=\"text-xs text-ink/60 mt-2 min-h-[1rem]\"></div>\n        </div>\n      </div>\n      <!-- Swap -->\n      <div class=\"flex md:flex-col flex-row items-center justify-center gap-2 no-print\">\n        <button id=\"btnSwap\" title=\"Swap start and end dates\" aria-label=\"Swap start and end dates\" class=\"w-11 h-11 rounded-full bg-terra text-white flex items-center justify-center shadow hover:bg-[#9A3412] transition-colors\">\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" aria-hidden=\"true\"><path d=\"M7 16V4m0 0L3 8m4-4l4 4M17 8v12m0 0l4-4m-4 4l-4-4\"/></svg>\n        </button>\n        <button id=\"btnToday\" class=\"text-xs font-bold text-terra underline underline-offset-2 hover:text-[#9A3412]\">today \u2192 end</button>\n      </div>\n      <!-- End date card -->\n      <div class=\"calpage\">\n        <div class=\"cap text-center py-1.5\">\n          <div id=\"endCap\" class=\"text-[11px] font-extrabold tracking-[0.2em] uppercase\">End month</div>\n        </div>\n        <div class=\"rings\" aria-hidden=\"true\"><span></span><span></span></div>\n        <div class=\"text-center px-4 pt-1 pb-3\">\n          <div id=\"endBig\" class=\"font-display font-black text-6xl text-ink leading-none\">\u2013</div>\n          <div id=\"endDow\" class=\"text-sm font-semibold text-terra mt-1\">Pick an end date</div>\n          <input id=\"dateEnd\" type=\"date\" aria-label=\"End date\" class=\"mt-3 w-full border border-linec rounded-lg px-3 py-2 text-sm bg-cream focus:border-terra\">\n          <div id=\"endLeap\" class=\"text-xs text-ink/60 mt-2 min-h-[1rem]\"></div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Options row -->\n    <div class=\"max-w-4xl mx-auto mt-4 flex flex-wrap items-center justify-center gap-x-6 gap-y-2 text-sm no-print\">\n      <label class=\"inline-flex items-center gap-2 cursor-pointer select-none\">\n        <input id=\"chkInclusive\" type=\"checkbox\" class=\"w-4 h-4 accent-[#C2410C]\">\n        <span class=\"font-medium\">Count both start <em>and</em> end dates</span>\n      </label>\n      <label class=\"inline-flex items-center gap-2 cursor-pointer select-none\">\n        <input id=\"chkTimes\" type=\"checkbox\" class=\"w-4 h-4 accent-[#C2410C]\">\n        <span class=\"font-medium\">Include times of day</span>\n      </label>\n    </div>\n    <div id=\"timeRow\" class=\"max-w-4xl mx-auto mt-3 hidden grid-cols-2 gap-4 no-print\">\n      <div class=\"flex items-center gap-2 justify-center\">\n        <label for=\"timeStart\" class=\"text-xs font-bold uppercase tracking-wider text-ink/60\">Start</label>\n        <input id=\"timeStart\" type=\"time\" class=\"border border-linec rounded-lg px-3 py-2 text-sm bg-white\">\n      </div>\n      <div class=\"flex items-center gap-2 justify-center\">\n        <label for=\"timeEnd\" class=\"text-xs font-bold uppercase tracking-wider text-ink/60\">End</label>\n        <input id=\"timeEnd\" type=\"time\" class=\"border border-linec rounded-lg px-3 py-2 text-sm bg-white\">\n      </div>\n    </div>\n\n    <!-- Big readout -->\n    <div class=\"max-w-4xl mx-auto mt-6\">\n      <div id=\"resultCard\" class=\"relative overflow-hidden rounded-2xl border border-linec bg-white shadow-[0_6px_24px_rgba(194,65,12,0.10)]\" aria-live=\"polite\">\n        <div class=\"paperbg absolute inset-0 opacity-40 pointer-events-none\" aria-hidden=\"true\"></div>\n        <div class=\"relative px-6 py-8 text-center\">\n          <div id=\"bigRange\" class=\"text-xs font-bold uppercase tracking-[0.18em] text-ink/50\">Awaiting two dates</div>\n          <div class=\"mt-2 flex items-baseline justify-center gap-3\">\n            <span id=\"bigDays\" class=\"font-display font-black text-7xl sm:text-8xl text-terra leading-none\">0</span>\n            <span class=\"font-display font-bold text-2xl text-ink/60\">days</span>\n          </div>\n          <div id=\"bigSub\" class=\"mt-3 text-sm text-ink/70 font-medium\">Pick a start and an end date above \u2014 the answer appears instantly.</div>\n          <div id=\"preciseLine\" class=\"mt-2 text-sm font-semibold text-gold hidden\"></div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Ticket grid -->\n    <div id=\"ticketGrid\" class=\"max-w-5xl mx-auto mt-6 grid grid-cols-2 lg:grid-cols-3 gap-5 hidden\">\n      <div class=\"ticket\">\n        <div class=\"percline\" aria-hidden=\"true\"></div>\n        <div class=\"ticket-top px-4 pt-4 pb-5 text-center\">\n          <div id=\"tBreakdown\" class=\"font-display font-extrabold text-2xl text-ink\">\u2013</div>\n          <div class=\"text-[11px] font-bold uppercase tracking-wider text-ink/50 mt-1\">Calendar breakdown</div>\n        </div>\n        <div class=\"ticket-bottom px-4 pt-5 pb-4 text-center\">\n          <div id=\"tBreakdownSub\" class=\"text-xs text-ink/60\">years \u00b7 months \u00b7 days</div>\n        </div>\n      </div>\n      <div class=\"ticket\">\n        <div class=\"percline\" aria-hidden=\"true\"></div>\n        <div class=\"ticket-top px-4 pt-4 pb-5 text-center\">\n          <div id=\"tWeeks\" class=\"font-display font-extrabold text-2xl text-ink\">\u2013</div>\n          <div class=\"text-[11px] font-bold uppercase tracking-wider text-ink/50 mt-1\">Weeks</div>\n        </div>\n        <div class=\"ticket-bottom px-4 pt-5 pb-4 text-center\">\n          <div id=\"tWeeksSub\" class=\"text-xs text-ink/60\">full weeks + leftover days</div>\n        </div>\n      </div>\n      <div class=\"ticket\">\n        <div class=\"percline\" aria-hidden=\"true\"></div>\n        <div class=\"ticket-top px-4 pt-4 pb-5 text-center\">\n          <div id=\"tWeekends\" class=\"font-display font-extrabold text-2xl text-terra\">\u2013</div>\n          <div class=\"text-[11px] font-bold uppercase tracking-wider text-ink/50 mt-1\">Weekend days</div>\n        </div>\n        <div class=\"ticket-bottom px-4 pt-5 pb-4 text-center\">\n          <div id=\"tWeekendsSub\" class=\"text-xs text-ink/60\">Saturdays + Sundays in span</div>\n        </div>\n      </div>\n      <div class=\"ticket\">\n        <div class=\"percline\" aria-hidden=\"true\"></div>\n        <div class=\"ticket-top px-4 pt-4 pb-5 text-center\">\n          <div id=\"tWeekdays\" class=\"font-display font-extrabold text-2xl text-ink\">\u2013</div>\n          <div class=\"text-[11px] font-bold uppercase tracking-wider text-ink/50 mt-1\">Weekdays</div>\n        </div>\n        <div class=\"ticket-bottom px-4 pt-5 pb-4 text-center\">\n          <div id=\"tWeekdaysSub\" class=\"text-xs text-ink/60\">Monday \u2013 Friday in span</div>\n        </div>\n      </div>\n      <div class=\"ticket\">\n        <div class=\"percline\" aria-hidden=\"true\"></div>\n        <div class=\"ticket-top px-4 pt-4 pb-5 text-center\">\n          <div id=\"tLeap\" class=\"font-display font-extrabold text-2xl text-gold\">\u2013</div>\n          <div class=\"text-[11px] font-bold uppercase tracking-wider text-ink/50 mt-1\">Leap days in span</div>\n        </div>\n        <div class=\"ticket-bottom px-4 pt-5 pb-4 text-center\">\n          <div id=\"tLeapSub\" class=\"text-xs text-ink/60\">Feb 29 occurrences counted</div>\n        </div>\n      </div>\n      <div class=\"ticket\">\n        <div class=\"percline\" aria-hidden=\"true\"></div>\n        <div class=\"ticket-top px-4 pt-4 pb-5 text-center\">\n          <div id=\"tPct\" class=\"font-display font-extrabold text-2xl text-terra\">\u2013</div>\n          <div class=\"text-[11px] font-bold uppercase tracking-wider text-ink/50 mt-1\">Of an average year</div>\n        </div>\n        <div class=\"ticket-bottom px-4 pt-5 pb-4 text-center\">\n          <div id=\"tPctSub\" class=\"text-xs text-ink/60\">this span as % of 365.25 days</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Copy + recents -->\n    <div class=\"max-w-4xl mx-auto mt-6 flex flex-col sm:flex-row items-center justify-center gap-3 no-print\">\n      <button id=\"btnCopy\" class=\"inline-flex items-center gap-2 bg-ink text-white font-bold text-sm rounded-full px-6 py-2.5 hover:bg-terra transition-colors disabled:opacity-40\" disabled>\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" aria-hidden=\"true\"><rect x=\"9\" y=\"9\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M5 15V5a2 2 0 0 1 2-2h10\"/></svg>\n        Copy summary\n      </button>\n      <span id=\"copyMsg\" class=\"text-xs font-semibold text-terra h-4\" aria-live=\"polite\"></span>\n    </div>\n    <div id=\"recentWrap\" class=\"max-w-4xl mx-auto mt-6 hidden no-print\">\n      <h3 class=\"text-xs font-bold uppercase tracking-[0.18em] text-ink/50 text-center\">Recent calculations</h3>\n      <div id=\"recentList\" class=\"mt-2 flex flex-wrap justify-center gap-2\"></div>\n    </div>\n  </section>\n</main>\n\n  <!-- ============ PANEL: MILESTONE ============ -->\n  <section id=\"panel-milestone\" role=\"tabpanel\" aria-labelledby=\"tab-milestone\" class=\"mt-6 hidden\">\n    <div class=\"max-w-3xl mx-auto calpage\">\n      <div class=\"cap text-center py-2\">\n        <div class=\"text-[11px] font-extrabold tracking-[0.2em] uppercase\">Milestone mode \u00b7 fun with big round numbers</div>\n      </div>\n      <div class=\"p-6 sm:p-8\">\n        <p class=\"text-center text-ink/70 text-sm sm:text-base\">Enter a birthdate (or any start date) and pick a day-count milestone. DaySpan tells you the exact calendar date it lands on.</p>\n        <div class=\"mt-5 grid sm:grid-cols-2 gap-4\">\n          <div>\n            <label for=\"msBirth\" class=\"text-xs font-bold uppercase tracking-wider text-ink/60\">Birthdate / start date</label>\n            <input id=\"msBirth\" type=\"date\" class=\"mt-1 w-full border border-linec rounded-lg px-3 py-2.5 text-sm bg-cream\">\n          </div>\n          <div>\n            <label for=\"msCustom\" class=\"text-xs font-bold uppercase tracking-wider text-ink/60\">Custom milestone (days)</label>\n            <input id=\"msCustom\" type=\"number\" min=\"1\" max=\"1000000\" placeholder=\"e.g. 12345\" class=\"mt-1 w-full border border-linec rounded-lg px-3 py-2.5 text-sm bg-cream\">\n          </div>\n        </div>\n        <div class=\"mt-4 flex flex-wrap justify-center gap-2 no-print\" role=\"group\" aria-label=\"Milestone presets\">\n          <button class=\"msPreset rounded-full border border-linec bg-white px-4 py-1.5 text-sm font-bold hover:border-terra hover:text-terra transition-colors\" data-n=\"1000\">1,000 days</button>\n          <button class=\"msPreset rounded-full border border-linec bg-white px-4 py-1.5 text-sm font-bold hover:border-terra hover:text-terra transition-colors\" data-n=\"5000\">5,000 days</button>\n          <button class=\"msPreset rounded-full border border-terra bg-terra text-white px-4 py-1.5 text-sm font-bold\" data-n=\"10000\">10,000 days</button>\n          <button class=\"msPreset rounded-full border border-linec bg-white px-4 py-1.5 text-sm font-bold hover:border-terra hover:text-terra transition-colors\" data-n=\"15000\">15,000 days</button>\n          <button class=\"msPreset rounded-full border border-linec bg-white px-4 py-1.5 text-sm font-bold hover:border-terra hover:text-terra transition-colors\" data-n=\"20000\">20,000 days</button>\n        </div>\n        <div id=\"msResult\" class=\"mt-6 hidden text-center\" aria-live=\"polite\">\n          <div class=\"text-xs font-bold uppercase tracking-[0.18em] text-ink/50\">You will be</div>\n          <div id=\"msBig\" class=\"font-display font-black text-4xl sm:text-5xl text-terra mt-1\">10,000 days old</div>\n          <div class=\"text-lg font-semibold mt-1\">on</div>\n          <div id=\"msDate\" class=\"font-display font-extrabold text-3xl sm:text-4xl text-ink mt-1\">\u2013</div>\n          <div id=\"msDow\" class=\"text-sm font-semibold text-ink/60 mt-1\">\u2013</div>\n          <div class=\"mt-5 max-w-md mx-auto\">\n            <div class=\"flex justify-between text-xs font-bold text-ink/60 mb-1\"><span>Progress</span><span id=\"msPct\">0%</span></div>\n            <div class=\"h-3 rounded-full bg-parch border border-linec overflow-hidden\">\n              <div id=\"msBar\" class=\"h-full rounded-full bg-gradient-to-r from-gold to-terra transition-all duration-500\" style=\"width:0%\"></div>\n            </div>\n            <div id=\"msRemain\" class=\"text-sm font-semibold text-ink/70 mt-2\">\u2013</div>\n          </div>\n        </div>\n        <div id=\"msHint\" class=\"mt-6 text-center text-sm text-ink/50\">Pick a birthdate to reveal your milestone date.</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ============ PANEL: JUMPER ============ -->\n  <section id=\"panel-jumper\" role=\"tabpanel\" aria-labelledby=\"tab-jumper\" class=\"mt-6 hidden\">\n    <div class=\"max-w-3xl mx-auto calpage\">\n      <div class=\"cap text-center py-2\">\n        <div class=\"text-[11px] font-extrabold tracking-[0.2em] uppercase\">Date jumper \u00b7 add or subtract days</div>\n      </div>\n      <div class=\"p-6 sm:p-8\">\n        <p class=\"text-center text-ink/70 text-sm sm:text-base\">Start from any date, jump forward or backward by N days. Handy for deadlines, due dates and anniversaries.</p>\n        <div class=\"mt-5 grid sm:grid-cols-[1fr_auto_1fr] gap-4 items-end\">\n          <div>\n            <label for=\"jBase\" class=\"text-xs font-bold uppercase tracking-wider text-ink/60\">Base date</label>\n            <input id=\"jBase\" type=\"date\" class=\"mt-1 w-full border border-linec rounded-lg px-3 py-2.5 text-sm bg-cream\">\n          </div>\n          <div class=\"flex gap-2 justify-center no-print\" role=\"group\" aria-label=\"Direction\">\n            <button id=\"jAdd\" aria-pressed=\"true\" class=\"rounded-full px-5 py-2.5 text-sm font-bold bg-terra text-white\">+ Add</button>\n            <button id=\"jSub\" aria-pressed=\"false\" class=\"rounded-full px-5 py-2.5 text-sm font-bold bg-white border border-linec text-ink\">\u2212 Subtract</button>\n          </div>\n          <div>\n            <label for=\"jDays\" class=\"text-xs font-bold uppercase tracking-wider text-ink/60\">Days</label>\n            <input id=\"jDays\" type=\"number\" min=\"0\" max=\"1000000\" value=\"30\" class=\"mt-1 w-full border border-linec rounded-lg px-3 py-2.5 text-sm bg-cream\">\n          </div>\n        </div>\n        <div class=\"mt-4 flex flex-wrap justify-center gap-2 no-print\" aria-label=\"Quick jumps\">\n          <button class=\"jQuick rounded-full border border-linec bg-white px-3.5 py-1.5 text-xs font-bold hover:border-terra hover:text-terra\" data-n=\"7\">\u00b17</button>\n          <button class=\"jQuick rounded-full border border-linec bg-white px-3.5 py-1.5 text-xs font-bold hover:border-terra hover:text-terra\" data-n=\"30\">\u00b130</button>\n          <button class=\"jQuick rounded-full border border-linec bg-white px-3.5 py-1.5 text-xs font-bold hover:border-terra hover:text-terra\" data-n=\"90\">\u00b190</button>\n          <button class=\"jQuick rounded-full border border-linec bg-white px-3.5 py-1.5 text-xs font-bold hover:border-terra hover:text-terra\" data-n=\"180\">\u00b1180</button>\n          <button class=\"jQuick rounded-full border border-linec bg-white px-3.5 py-1.5 text-xs font-bold hover:border-terra hover:text-terra\" data-n=\"365\">\u00b1365</button>\n        </div>\n        <div id=\"jResult\" class=\"mt-6 hidden text-center\" aria-live=\"polite\">\n          <div class=\"text-xs font-bold uppercase tracking-[0.18em] text-ink/50\">Resulting date</div>\n          <div id=\"jDate\" class=\"font-display font-black text-4xl sm:text-5xl text-terra mt-1\">\u2013</div>\n          <div id=\"jDow\" class=\"text-sm font-semibold text-ink/60 mt-1\">\u2013</div>\n        </div>\n        <div id=\"jHint\" class=\"mt-6 text-center text-sm text-ink/50\">Choose a base date and a number of days.</div>\n      </div>\n    </div>\n  </section>\n\n<!-- ================= BOTTOM AD ================= -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ================= SEO ARTICLE ================= -->\n<section class=\"mx-auto max-w-4xl px-4 sm:px-6 pb-10\">\n  <article id=\"seo-article\" class=\"bg-white border border-linec rounded-2xl p-6 sm:p-10 shadow-sm\">\n    <h2 class=\"font-display font-extrabold text-3xl text-ink\">The Complete Guide to Date Duration Calculations</h2>\n    <p class=\"text-sm text-ink/50 mt-1\">By the DaySpan team \u00b7 Last updated September 2026</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">What a date duration calculator actually does</h3>\n    <p class=\"mt-3 leading-relaxed\">A date duration calculator answers one deceptively simple question: how much time passes between two calendar dates? The answer can be expressed in many units \u2014 total days, weeks, months, years, hours, minutes and seconds \u2014 and each unit tells a slightly different story. Project managers use day counts to track deadlines, HR teams use them for notice periods and benefit eligibility, travellers use them for visa validity, and curious minds use them to find out exactly how many days old they are. DaySpan computes all of these answers at once, instantly, from a single pair of dates.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Why counting days is harder than it looks</h3>\n    <p class=\"mt-3 leading-relaxed\">If every month had 30 days and every year had 365, date math would be trivial. Real calendars refuse to cooperate. Months alternate between 28, 29, 30 and 31 days, and the Gregorian calendar inserts an extra day \u2014 February 29 \u2014 into leap years. A year is a leap year if it is divisible by 4, except for century years, which must also be divisible by 400. That is why 2024 and 2000 were leap years but 1900 was not. Any span that crosses a February 29 contains one more day than a naive 365-day-per-year estimate would suggest, and long spans accumulate several of these leap days. DaySpan counts every February 29 inside your span explicitly, so the total is always calendar-accurate.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Inclusive versus exclusive: the fencepost problem</h3>\n    <p class=\"mt-3 leading-relaxed\">Ask two people for the days between Monday and Wednesday and you may get two answers: two days or three. Both are defensible. The exclusive count measures the gap \u2014 Monday to Wednesday is 2 days \u2014 while the inclusive count includes both endpoints, giving 3. Programmers call this the fencepost problem: the number of fence posts is one more than the number of gaps between them. Contracts, hotel bookings and project plans each pick a convention, which is why it matters that a calculator states its convention clearly. DaySpan defaults to the exclusive gap count used by most date libraries, and offers a one-tap toggle to include both the start and end dates when your use case needs it.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">The timezone and daylight-saving trap</h3>\n    <p class=\"mt-3 leading-relaxed\">A surprising number of online calculators get the wrong answer near daylight-saving transitions. The bug is subtle: they convert each date to a local-midnight timestamp and divide the millisecond difference by 86,400,000. On the day clocks spring forward, that \"day\" is only 23 hours long, so the division yields 0.958 days, which rounds down to zero \u2014 an off-by-one error. The robust fix, and the one DaySpan uses, is to perform every calculation in UTC, where every calendar day is exactly 86,400 seconds and daylight saving simply does not exist. UTC-based date math is immune to timezones, DST jumps and the quirks of any particular browser locale, which is why it is the professional standard for date libraries.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Breaking a span into years, months and days</h3>\n    <p class=\"mt-3 leading-relaxed\">Total days are precise, but \"1 year, 2 months and 5 days\" is how humans actually think about durations. Converting between the two requires calendar-aware borrowing, much like subtracting multi-digit numbers. You subtract the years, then the months, then the days \u2014 and when the day subtraction goes negative, you borrow a month from the end date, adding back however many days that borrowed month actually contained. Borrowing from March gives you 28 or 29 days depending on leap-year status; borrowing from May gives 31. DaySpan performs this borrow correctly for every month, so the breakdown always reconstructs the exact end date when added back to the start.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Weekends, weekdays and the rhythm of a span</h3>\n    <p class=\"mt-3 leading-relaxed\">A raw day count hides the rhythm of a period. A 30-day span contains either 8 or 10 weekend days depending on where it starts, and that difference matters for staffing, payroll and delivery planning. DaySpan tallies Saturdays and Sundays separately from Monday-to-Friday weekdays, using modular arithmetic on the day of the week rather than slow day-by-day iteration. The result answers practical questions instantly: how many working days are in this quarter, how many weekends fall inside this project phase, and what share of the span is actually time off.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Reverse answers: seeing a duration from the other side</h3>\n    <p class=\"mt-3 leading-relaxed\">Most calculators answer \"how long\" and stop. DaySpan also answers the questions you did not know to ask. What percentage of an average year does this span represent? Dividing by 365.25 \u2014 the average Gregorian year length \u2014 turns an abstract day count into an intuitive share: 182 days is essentially half a year, 91 days is a quarter. How many leap days did the span absorb? That number explains why a \"ten-year\" span is 3,652 or 3,653 days depending on where it falls. These reverse perspectives turn a single subtraction into genuine insight, which is exactly what a great calculator should do.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Day-of-week callouts and leap-year status</h3>\n    <p class=\"mt-3 leading-relaxed\">Every date has a personality: the weekday it falls on and whether its year is a leap year. Knowing that your start date was a Sunday and your end date is a Tuesday immediately grounds the numbers \u2014 a span that begins and ends on weekends feels different from one spanning the work week. DaySpan derives the weekday for both endpoints using UTC-based day-of-week arithmetic, the same mathematics behind classic mental-calculation algorithms like the Doomsday rule. It also flags leap-year status for each year involved, so you can see at a glance whether February 29 played a role in your result.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Adding and subtracting days: the date jumper</h3>\n    <p class=\"mt-3 leading-relaxed\">The inverse operation is just as useful as the difference: given a start date, what date lands exactly N days later? This is the math behind payment terms (\"net 30\"), warranty periods, subscription renewals, medical follow-ups and travel itineraries. Doing it by hand means flipping calendar pages and miscounting month lengths; the date jumper does it in one step, correctly crossing month and year boundaries, including leap days. Subtracting works the same way \u2014 count backwards from a deadline to find the latest safe start date.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Milestone math: the famous 10,000 days</h3>\n    <p class=\"mt-3 leading-relaxed\">Round-number milestones have a special charm. Reaching 10,000 days old \u2014 roughly 27 years and 4 months \u2014 is a once-in-a-lifetime date worth celebrating, and the same arithmetic powers wedding anniversaries measured in days, \"1,000 days since launch\" company milestones and sobriety counters. The calculation is simple addition on the calendar, but the delight is in the answer: an exact future date, its weekday, and a countdown of how many days remain. DaySpan's milestone mode also shows your progress as a percentage, turning a distant date into a journey you can watch unfold.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">Real-world uses for precise date durations</h3>\n    <p class=\"mt-3 leading-relaxed\">Accurate day counts quietly power large parts of modern life. In project management, dependencies and critical paths are measured in working days, and a miscounted weekend can shift a launch. In HR and payroll, notice periods, probation lengths and leave accruals are defined in calendar or business days, and disputes often hinge on a single day. In medicine, pregnancy is tracked as 280 days from the last menstrual period, and medication schedules depend on exact intervals. In finance, interest accrues per day under day-count conventions, and bond maturities are set years ahead. In law, filing deadlines and statutes of limitation are unforgiving of arithmetic slips. In travel, visa-free stays are counted in days, and overstaying by one can mean fines or bans. A trustworthy calculator earns its place by being right in every one of these contexts.</p>\n\n    <h3 class=\"font-display font-bold text-2xl text-terra mt-8\">How DaySpan computes your answer</h3>\n    <p class=\"mt-3 leading-relaxed\">Every DaySpan calculation follows three principles. First, all date math happens in UTC, so timezones and daylight-saving transitions can never corrupt the result. Second, month and year breakdowns use true calendar arithmetic with correct borrowing, not the rough 30.44-day average month. Third, everything runs instantly and entirely in your browser \u2014 your dates are never sent to a server, stored, or tracked. Type two dates and the dashboard updates live: total days, weeks, the calendar breakdown, weekend and weekday tallies, leap days in the span, the span's share of an average year, and day-of-week plus leap-year callouts for both endpoints. No signup, no paywall, no watermark \u2014 just the answer, as many times as you need it.</p>\n  </article>\n\n  <!-- FAQs -->\n  <div class=\"mt-10\">\n    <h2 class=\"font-display font-extrabold text-3xl text-ink text-center\">Frequently asked questions</h2>\n    <div class=\"mt-6 space-y-3 max-w-3xl mx-auto\">\n      <details class=\"faq-item bg-white border border-linec rounded-xl overflow-hidden\">\n        <summary class=\"cursor-pointer px-5 py-4 flex items-center justify-between gap-4 font-bold text-ink list-none\">\n          <span>How does DaySpan count the days between two dates?</span>\n          <svg class=\"faq-chev shrink-0 text-terra\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </summary>\n        <div class=\"px-5 pb-5 text-sm leading-relaxed text-ink/75\">DaySpan counts the exclusive gap between the two dates: the number of midnights from the start date up to, but not including, the end date. So Monday to Wednesday is 2 days. If your use case needs both endpoints counted \u2014 common for bookings and leave requests \u2014 tick \"Count both start and end dates\" and DaySpan adds one. The order does not matter: entering the later date first gives the same result.</div>\n      </details>\n      <details class=\"faq-item bg-white border border-linec rounded-xl overflow-hidden\">\n        <summary class=\"cursor-pointer px-5 py-4 flex items-center justify-between gap-4 font-bold text-ink list-none\">\n          <span>Why do different date calculators sometimes disagree by one day?</span>\n          <svg class=\"faq-chev shrink-0 text-terra\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </summary>\n        <div class=\"px-5 pb-5 text-sm leading-relaxed text-ink/75\">Almost always, the culprit is timezone or daylight-saving handling. Calculators that convert dates to local-midnight timestamps and divide by 86,400,000 milliseconds lose or gain an hour on DST transition days, and rounding turns that hour into a missing or extra day. DaySpan avoids this entirely by doing all date math in UTC, where every calendar day is exactly 24 hours. A one-day disagreement can also come from the inclusive-versus-exclusive convention, which DaySpan lets you toggle explicitly.</div>\n      </details>\n      <details class=\"faq-item bg-white border border-linec rounded-xl overflow-hidden\">\n        <summary class=\"cursor-pointer px-5 py-4 flex items-center justify-between gap-4 font-bold text-ink list-none\">\n          <span>How are leap years handled in the calculation?</span>\n          <svg class=\"faq-chev shrink-0 text-terra\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </summary>\n        <div class=\"px-5 pb-5 text-sm leading-relaxed text-ink/75\">DaySpan uses the full Gregorian rule: a year is a leap year if divisible by 4, except century years, which must be divisible by 400 \u2014 so 2024 qualifies but 1900 does not. Every February 29 falling inside your span is counted individually and shown as \"Leap days in span.\" Both endpoint dates also get a leap-year callout, so you can see at a glance whether a leap day influenced your result.</div>\n      </details>\n      <details class=\"faq-item bg-white border border-linec rounded-xl overflow-hidden\">\n        <summary class=\"cursor-pointer px-5 py-4 flex items-center justify-between gap-4 font-bold text-ink list-none\">\n          <span>How is the \"years, months, days\" breakdown calculated?</span>\n          <svg class=\"faq-chev shrink-0 text-terra\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </summary>\n        <div class=\"px-5 pb-5 text-sm leading-relaxed text-ink/75\">DaySpan uses calendar-aware subtraction with borrowing. It subtracts years, then months, then days; when the day subtraction goes negative it borrows one month from the end date and adds that month's true length (28, 29, 30 or 31 days). This means adding the breakdown back to the start date always reconstructs the end date exactly \u2014 unlike rough estimates based on a 30.44-day average month.</div>\n      </details>\n      <details class=\"faq-item bg-white border border-linec rounded-xl overflow-hidden\">\n        <summary class=\"cursor-pointer px-5 py-4 flex items-center justify-between gap-4 font-bold text-ink list-none\">\n          <span>What does \"this span is X% of an average year\" mean?</span>\n          <svg class=\"faq-chev shrink-0 text-terra\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </summary>\n        <div class=\"px-5 pb-5 text-sm leading-relaxed text-ink/75\">It expresses your day count as a share of 365.25 days \u2014 the average length of a Gregorian calendar year, accounting for leap years. A 182-day span reads as roughly 50% of a year, and 91 days as about 25%. It is a \"reverse answer\": instead of asking how long the span is, it tells you how big the span feels relative to a year you already understand.</div>\n      </details>\n      <details class=\"faq-item bg-white border border-linec rounded-xl overflow-hidden\">\n        <summary class=\"cursor-pointer px-5 py-4 flex items-center justify-between gap-4 font-bold text-ink list-none\">\n          <span>Is my data private? Do I need an account?</span>\n          <svg class=\"faq-chev shrink-0 text-terra\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </summary>\n        <div class=\"px-5 pb-5 text-sm leading-relaxed text-ink/75\">Yes, completely. DaySpan runs 100% in your browser: every calculation happens locally in JavaScript and your dates are never sent to any server. There is no signup, no paywall and no watermark. Your recent calculations are stored only in your own browser's local storage, and you can clear them any time by clearing site data.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n<!-- ================= JSON-LD ================= -->\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    { \"@type\": \"Question\", \"name\": \"How does DaySpan count the days between two dates?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"DaySpan counts the exclusive gap between the two dates: the number of midnights from the start date up to, but not including, the end date. An optional toggle counts both endpoints. Date order does not matter.\" } },\n    { \"@type\": \"Question\", \"name\": \"Why do different date calculators sometimes disagree by one day?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The usual cause is timezone or daylight-saving handling in calculators that divide local-midnight timestamps by 86400000 milliseconds. DaySpan performs all date math in UTC, where every calendar day is exactly 24 hours, eliminating this error.\" } },\n    { \"@type\": \"Question\", \"name\": \"How are leap years handled in the calculation?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"DaySpan uses the Gregorian rule: a year is a leap year if divisible by 4, except century years which must be divisible by 400. Every February 29 inside the span is counted and shown separately.\" } },\n    { \"@type\": \"Question\", \"name\": \"How is the years, months, days breakdown calculated?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"DaySpan uses calendar-aware subtraction with borrowing: when the day subtraction goes negative it borrows one month from the end date and adds that month's true length, so the breakdown always reconstructs the end date exactly.\" } },\n    { \"@type\": \"Question\", \"name\": \"What does this span is X% of an average year mean?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"It expresses the day count as a share of 365.25 days, the average Gregorian year length. A 182-day span is roughly 50% of a year; 91 days is about 25%.\" } },\n    { \"@type\": \"Question\", \"name\": \"Is my data private? Do I need an account?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Yes. DaySpan runs entirely in your browser with no server calls, no signup, no paywall and no watermark. Recent calculations are stored only in your browser's local storage.\" } }\n  ]\n}\n</script>\n\n<!-- ================= FOOTER ================= -->\n<footer class=\"border-t border-linec bg-parch/60\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-4\">\n    <div class=\"flex items-center gap-2\">\n      <span class=\"font-display font-extrabold text-xl text-terra\">DaySpan</span>\n      <span class=\"text-xs text-ink/50\">\u00b7 Free date duration calculator</span>\n    </div>\n    <nav class=\"flex items-center gap-5 text-sm font-semibold\" aria-label=\"Footer navigation\">\n      <a href=\"#top\" class=\"text-ink/70 hover:text-terra\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"text-ink/70 hover:text-terra\">More Tools</a>\n    </nav>\n  </div>\n  <div class=\"text-center text-xs text-ink/40 pb-6\">All calculations happen in your browser. Dates are never uploaded or stored on any server.</div>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<script>\n/*__PURE_START__*/\n/* DaySpan pure date logic \u2014 no DOM access. All math in UTC to avoid timezone/DST off-by-one errors. */\nvar MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];\nvar MONTH_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\nvar DOW_NAMES = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];\nvar DAY_MS = 86400000;\n\nfunction isLeapYear(y) {\n  return (y % 4 === 0 && y % 100 !== 0) || (y % 400 === 0);\n}\nfunction daysInMonth(y, m0) { /* m0: 0-indexed month */\n  return new Date(Date.UTC(y, m0 + 1, 0)).getUTCDate();\n}\nfunction parseDate(str) { /* 'YYYY-MM-DD' -> {y,m,d} (m 0-indexed) or null */\n  if (typeof str !== 'string') return null;\n  var m = /^(\\d{4})-(\\d{1,2})-(\\d{1,2})$/.exec(str.trim());\n  if (!m) return null;\n  var y = parseInt(m[1], 10), mo = parseInt(m[2], 10), d = parseInt(m[3], 10);\n  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;\n  if (d > daysInMonth(y, mo - 1)) return null;\n  return { y: y, m: mo - 1, d: d };\n}\nfunction toUTCms(p) { return Date.UTC(p.y, p.m, p.d); }\nfunction pad2(n) { return (n < 10 ? '0' : '') + n; }\nfunction msToISO(ms) {\n  var dt = new Date(ms);\n  return dt.getUTCFullYear() + '-' + pad2(dt.getUTCMonth() + 1) + '-' + pad2(dt.getUTCDate());\n}\nfunction dayOfWeekIndex(p) { return new Date(toUTCms(p)).getUTCDay(); }\nfunction dayOfWeekName(p) { return DOW_NAMES[dayOfWeekIndex(p)]; }\nfunction orderedPair(aStr, bStr) { /* returns [startMs, endMs] with start <= end, or null */\n  var pa = parseDate(aStr), pb = parseDate(bStr);\n  if (!pa || !pb) return null;\n  var sa = toUTCms(pa), sb = toUTCms(pb);\n  return sa <= sb ? [sa, sb] : [sb, sa];\n}\nfunction daysBetween(aStr, bStr) { /* exclusive gap, absolute; NaN on invalid */\n  var pr = orderedPair(aStr, bStr);\n  if (!pr) return NaN;\n  return Math.round((pr[1] - pr[0]) / DAY_MS);\n}\nfunction fullBreakdown(aStr, bStr) { /* calendar-accurate {years, months, days} or null */\n  var pa = parseDate(aStr), pb = parseDate(bStr);\n  if (!pa || !pb) return null;\n  var s = pa, e = pb;\n  if (toUTCms(s) > toUTCms(e)) { s = pb; e = pa; }\n  var eMs = toUTCms(e);\n  /* count whole months by advancing the start date (clamping day to month length) */\n  var y = s.y, m = s.m, totalMonths = 0;\n  for (;;) {\n    var nm = m + 1, ny = y;\n    if (nm > 11) { nm = 0; ny = y + 1; }\n    var cand = Date.UTC(ny, nm, Math.min(s.d, daysInMonth(ny, nm)));\n    if (cand > eMs) break;\n    y = ny; m = nm; totalMonths++;\n  }\n  var advMs = Date.UTC(y, m, Math.min(s.d, daysInMonth(y, m)));\n  var days = Math.round((eMs - advMs) / DAY_MS);\n  return { years: Math.floor(totalMonths / 12), months: totalMonths % 12, days: days };\n}\nfunction weekendCount(aStr, bStr, inclusive) { /* {saturdays, sundays, weekends, weekdays, totalDays} or null */\n  var pr = orderedPair(aStr, bStr);\n  if (!pr) return null;\n  var endEx = inclusive ? pr[1] + DAY_MS : pr[1];\n  var total = Math.round((endEx - pr[0]) / DAY_MS);\n  if (total <= 0) return { saturdays: 0, sundays: 0, weekends: 0, weekdays: 0, totalDays: 0 };\n  var startDow = new Date(pr[0]).getUTCDay();\n  var fullWeeks = Math.floor(total / 7), rem = total % 7;\n  var sat = fullWeeks, sun = fullWeeks;\n  for (var i = 0; i < rem; i++) {\n    var dow = (startDow + i) % 7;\n    if (dow === 6) sat++;\n    else if (dow === 0) sun++;\n  }\n  return { saturdays: sat, sundays: sun, weekends: sat + sun, weekdays: total - sat - sun, totalDays: total };\n}\nfunction leapDaysInSpan(aStr, bStr, inclusive) { /* count of Feb 29 in [start, end) \u2014 or [start, end] if inclusive; null on invalid */\n  var pr = orderedPair(aStr, bStr);\n  if (!pr) return null;\n  var pa = parseDate(aStr), pb = parseDate(bStr);\n  var endEx = inclusive ? pr[1] + DAY_MS : pr[1];\n  var y0 = Math.min(pa.y, pb.y), y1 = Math.max(pa.y, pb.y), count = 0;\n  for (var y = y0; y <= y1; y++) {\n    if (!isLeapYear(y)) continue;\n    var feb29 = Date.UTC(y, 1, 29);\n    if (feb29 >= pr[0] && feb29 < endEx) count++;\n  }\n  return count;\n}\nfunction percentOfYear(totalDays) { /* span as % of average Gregorian year (365.25d), 2dp */\n  if (!isFinite(totalDays) || totalDays < 0) return NaN;\n  return Math.round((totalDays / 365.25) * 10000) / 100;\n}\nfunction milestoneDate(birthStr, n) { /* {date, dow, leapYear} or null */\n  var p = parseDate(birthStr);\n  if (!p || !isFinite(n)) return null;\n  n = Math.floor(Math.abs(n));\n  var ms = toUTCms(p) + n * DAY_MS;\n  var iso = msToISO(ms);\n  var dt = new Date(ms);\n  return { date: iso, dow: DOW_NAMES[dt.getUTCDay()], leapYear: isLeapYear(dt.getUTCFullYear()), n: n };\n}\nfunction milestoneProgress(birthStr, n, todayStr) { /* progress toward milestone; null on invalid */\n  var res = milestoneDate(birthStr, n);\n  if (!res) return null;\n  var out = { target: res, livedDays: null, remainingDays: null, percent: null, passed: false };\n  var t = todayStr ? parseDate(todayStr) : null;\n  if (!t) return out;\n  var p = parseDate(birthStr);\n  var targetMs = Date.UTC(+res.date.slice(0, 4), +res.date.slice(5, 7) - 1, +res.date.slice(8, 10));\n  var lived = Math.max(0, Math.round((toUTCms(t) - toUTCms(p)) / DAY_MS));\n  var remaining = Math.round((targetMs - toUTCms(t)) / DAY_MS);\n  out.livedDays = lived;\n  out.remainingDays = remaining;\n  out.percent = Math.min(100, Math.max(0, Math.round((lived / res.n) * 1000) / 10));\n  out.passed = remaining < 0;\n  return out;\n}\nfunction addDays(dateStr, n) { /* {date, dow, leapYear} or null */\n  var p = parseDate(dateStr);\n  if (!p || !isFinite(n)) return null;\n  n = Math.trunc(n);\n  var ms = toUTCms(p) + n * DAY_MS;\n  var iso = msToISO(ms);\n  var dt = new Date(ms);\n  return { date: iso, dow: DOW_NAMES[dt.getUTCDay()], leapYear: isLeapYear(dt.getUTCFullYear()) };\n}\nfunction parseTime(str) { /* 'HH:MM' -> {h, mi} or null */\n  if (typeof str !== 'string') return null;\n  var m = /^(\\d{1,2}):(\\d{2})$/.exec(str.trim());\n  if (!m) return null;\n  var h = +m[1], mi = +m[2];\n  if (h > 23 || mi > 59) return null;\n  return { h: h, mi: mi };\n}\nfunction preciseDuration(aStr, aTime, bStr, bTime) { /* with times-of-day; {days,hours,minutes,seconds,totalHours} or null */\n  var pa = parseDate(aStr), pb = parseDate(bStr);\n  if (!pa || !pb) return null;\n  var ta = parseTime(aTime) || { h: 0, mi: 0 };\n  var tb = parseTime(bTime) || { h: 0, mi: 0 };\n  var sa = Date.UTC(pa.y, pa.m, pa.d, ta.h, ta.mi);\n  var sb = Date.UTC(pb.y, pb.m, pb.d, tb.h, tb.mi);\n  if (sa > sb) { var t = sa; sa = sb; sb = t; }\n  var diff = sb - sa;\n  var days = Math.floor(diff / DAY_MS); diff -= days * DAY_MS;\n  var hours = Math.floor(diff / 3600000); diff -= hours * 3600000;\n  var minutes = Math.floor(diff / 60000); diff -= minutes * 60000;\n  var seconds = Math.floor(diff / 1000);\n  return { days: days, hours: hours, minutes: minutes, seconds: seconds };\n}\nfunction validateDates(aStr, bStr) {\n  var pa = parseDate(aStr), pb = parseDate(bStr);\n  if (!aStr && !bStr) return '';\n  if (!pa && aStr) return 'Start date is not a valid calendar date.';\n  if (!pb && bStr) return 'End date is not a valid calendar date.';\n  return '';\n}\nfunction formatLong(isoStr) { /* '2026-09-29' -> '29 Sep 2026' */\n  var p = parseDate(isoStr);\n  if (!p) return '';\n  return p.d + ' ' + MONTH_SHORT[p.m] + ' ' + p.y;\n}\nfunction fmtNum(n) {\n  if (!isFinite(n)) return '\u2013';\n  return Math.round(n).toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',');\n}\nfunction summaryText(r) { /* copyable plain-text summary from a result object */\n  if (!r) return '';\n  var lines = [];\n  lines.push('DaySpan \u2014 date duration summary');\n  lines.push(r.aLabel + ' (' + r.aDow + ')  \u2192  ' + r.bLabel + ' (' + r.bDow + ')' + (r.inclusive ? '  [inclusive]' : ''));\n  lines.push('Total: ' + fmtNum(r.totalDays) + ' days');\n  lines.push('= ' + r.brk.years + ' years, ' + r.brk.months + ' months, ' + r.brk.days + ' days');\n  lines.push('= ' + fmtNum(r.weeks) + ' weeks and ' + r.weeksRem + ' days');\n  lines.push('Weekends: ' + fmtNum(r.wc.weekends) + ' days (' + r.wc.saturdays + ' Sat + ' + r.wc.sundays + ' Sun) \u00b7 Weekdays: ' + fmtNum(r.wc.weekdays));\n  lines.push('Leap days in span: ' + r.leapDays + ' \u00b7 ' + r.pctYear + '% of an average year');\n  if (r.precise) lines.push('Precise: ' + r.precise.days + 'd ' + r.precise.hours + 'h ' + r.precise.minutes + 'm ' + r.precise.seconds + 's');\n  return lines.join('\\n');\n}\n/*__PURE_END__*/\n\n/* ================= UI WIRING (DOM) ================= */\n(function () {\n  'use strict';\n  function $(id) { return document.getElementById(id); }\n  var RECENT_KEY = 'dayspan-recent-v1';\n  var lastResult = null;\n\n  /* ---------- tabs ---------- */\n  var tabs = ['duration', 'milestone', 'jumper'];\n  tabs.forEach(function (name) {\n    $('tab-' + name).addEventListener('click', function () {\n      tabs.forEach(function (n) {\n        $('tab-' + n).setAttribute('aria-selected', n === name ? 'true' : 'false');\n        $('panel-' + n).classList.toggle('hidden', n !== name);\n      });\n    });\n  });\n\n  /* ---------- calendar page cards ---------- */\n  function paintCalCard(prefix, iso) {\n    var p = parseDate(iso);\n    if (!p) {\n      $(prefix + 'Cap').textContent = prefix === 'start' ? 'Start month' : 'End month';\n      $(prefix + 'Big').textContent = '\u2013';\n      $(prefix + 'Dow').textContent = prefix === 'start' ? 'Pick a start date' : 'Pick an end date';\n      $(prefix + 'Leap').textContent = '';\n      return;\n    }\n    $(prefix + 'Cap').textContent = MONTH_NAMES[p.m] + ' ' + p.y;\n    $(prefix + 'Big').textContent = p.d;\n    $(prefix + 'Dow').textContent = dayOfWeekName(p);\n    $(prefix + 'Leap').textContent = p.y + (isLeapYear(p.y) ? ' is a leap year' : ' is not a leap year');\n  }\n\n  function currentResult() { return lastResult; }\n\n  /* ---------- main recalculation (live) ---------- */\n  function recalc() {\n    var a = $('dateStart').value, b = $('dateEnd').value;\n    paintCalCard('start', a);\n    paintCalCard('end', b);\n    var err = validateDates(a, b);\n    if (!a || !b || err || !parseDate(a) || !parseDate(b)) {\n      $('bigRange').textContent = err || 'Awaiting two dates';\n      $('bigDays').textContent = '0';\n      $('bigSub').textContent = err || 'Pick a start and an end date above \u2014 the answer appears instantly.';\n      $('preciseLine').classList.add('hidden');\n      $('ticketGrid').classList.add('hidden');\n      $('btnCopy').disabled = true;\n      lastResult = null;\n      return;\n    }\n    var inclusive = $('chkInclusive').checked;\n    var pr = orderedPair(a, b);\n    var total = daysBetween(a, b) + (inclusive ? 1 : 0);\n    var brk = fullBreakdown(a, b);\n    var wc = weekendCount(a, b, inclusive);\n    var leap = leapDaysInSpan(a, b, inclusive);\n    var pct = percentOfYear(total);\n    var pa = parseDate(a), pb = parseDate(b);\n    var weeks = Math.floor(total / 7), weeksRem = total % 7;\n    var precise = null;\n    if ($('chkTimes').checked) {\n      precise = preciseDuration(a, $('timeStart').value, b, $('timeEnd').value);\n    }\n    var swapped = toUTCms(pa) > toUTCms(pb);\n    var first = swapped ? b : a, second = swapped ? a : b;\n    var r = {\n      aLabel: formatLong(first), bLabel: formatLong(second),\n      aDow: dayOfWeekName(parseDate(first)), bDow: dayOfWeekName(parseDate(second)),\n      totalDays: total, inclusive: inclusive, brk: brk, wc: wc,\n      leapDays: leap, pctYear: pct, weeks: weeks, weeksRem: weeksRem, precise: precise\n    };\n    lastResult = r;\n\n    $('bigRange').textContent = r.aLabel + '  \u2192  ' + r.bLabel;\n    $('bigDays').textContent = fmtNum(total);\n    var bits = [];\n    if (brk.years) bits.push(brk.years + (brk.years === 1 ? ' year' : ' years'));\n    if (brk.months) bits.push(brk.months + (brk.months === 1 ? ' month' : ' months'));\n    if (brk.days || !bits.length) bits.push(brk.days + (brk.days === 1 ? ' day' : ' days'));\n    $('bigSub').textContent = 'That is ' + bits.join(', ') + (inclusive ? ' (both endpoints counted).' : '.');\n    if (precise && (precise.hours || precise.minutes || precise.seconds || $('timeStart').value || $('timeEnd').value)) {\n      $('preciseLine').textContent = 'Precise: ' + precise.days + 'd ' + precise.hours + 'h ' + precise.minutes + 'm ' + precise.seconds + 's';\n      $('preciseLine').classList.remove('hidden');\n    } else {\n      $('preciseLine').classList.add('hidden');\n    }\n    /* tickets */\n    $('ticketGrid').classList.remove('hidden');\n    $('tBreakdown').textContent = brk.years + 'y ' + brk.months + 'm ' + brk.days + 'd';\n    $('tBreakdownSub').textContent = 'calendar-accurate' + (swapped ? ' \u00b7 dates auto-ordered' : '');\n    $('tWeeks').textContent = fmtNum(weeks) + ' wks';\n    $('tWeeksSub').textContent = '+ ' + weeksRem + ' leftover day' + (weeksRem === 1 ? '' : 's');\n    $('tWeekends').textContent = fmtNum(wc.weekends);\n    $('tWeekendsSub').textContent = wc.saturdays + ' Saturdays + ' + wc.sundays + ' Sundays';\n    $('tWeekdays').textContent = fmtNum(wc.weekdays);\n    $('tWeekdaysSub').textContent = 'Monday \u2013 Friday in span';\n    $('tLeap').textContent = leap;\n    $('tLeapSub').textContent = leap === 1 ? 'one Feb 29 inside this span' : 'Feb 29 occurrences counted';\n    $('tPct').textContent = pct + '%';\n    $('tPctSub').textContent = 'of a 365.25-day average year';\n    $('btnCopy').disabled = false;\n    saveRecent(a, b, total);\n  }\n\n  ['dateStart', 'dateEnd', 'timeStart', 'timeEnd'].forEach(function (id) {\n    $(id).addEventListener('input', recalc);\n    $(id).addEventListener('change', recalc);\n  });\n  $('chkInclusive').addEventListener('change', recalc);\n  $('chkTimes').addEventListener('change', function () {\n    $('timeRow').classList.toggle('hidden', !this.checked);\n    $('timeRow').classList.toggle('grid', this.checked);\n    recalc();\n  });\n  $('btnSwap').addEventListener('click', function () {\n    var s = $('dateStart').value;\n    $('dateStart').value = $('dateEnd').value;\n    $('dateEnd').value = s;\n    recalc();\n  });\n  $('btnToday').addEventListener('click', function () {\n    $('dateEnd').value = msToISO(Date.now());\n    recalc();\n  });\n\n  /* ---------- copy summary ---------- */\n  $('btnCopy').addEventListener('click', function () {\n    var r = currentResult();\n    if (!r) return;\n    var text = summaryText(r);\n    function done() {\n      $('copyMsg').textContent = 'Copied to clipboard \u2713';\n      setTimeout(function () { $('copyMsg').textContent = ''; }, 2500);\n    }\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });\n    } else { fallbackCopy(text); done(); }\n  });\n  function fallbackCopy(text) {\n    var ta = document.createElement('textarea');\n    ta.value = text;\n    ta.style.position = 'fixed'; ta.style.opacity = '0';\n    document.body.appendChild(ta); ta.select();\n    try { document.execCommand('copy'); } catch (e) {}\n    document.body.removeChild(ta);\n  }\n\n  /* ---------- recent calculations (localStorage) ---------- */\n  function loadRecent() {\n    try { return JSON.parse(localStorage.getItem(RECENT_KEY) || '[]'); }\n    catch (e) { return []; }\n  }\n  function saveRecent(a, b, total) {\n    try {\n      var list = loadRecent().filter(function (e) { return !(e.a === a && e.b === b); });\n      list.unshift({ a: a, b: b, total: total });\n      localStorage.setItem(RECENT_KEY, JSON.stringify(list.slice(0, 8)));\n      renderRecent();\n    } catch (e) {}\n  }\n  function renderRecent() {\n    var list = loadRecent();\n    $('recentWrap').classList.toggle('hidden', !list.length);\n    var wrap = $('recentList');\n    wrap.innerHTML = '';\n    list.forEach(function (e) {\n      var btn = document.createElement('button');\n      btn.className = 'text-xs font-semibold border border-linec bg-white rounded-full px-3 py-1.5 hover:border-terra hover:text-terra transition-colors';\n      btn.textContent = formatLong(e.a) + ' \u2192 ' + formatLong(e.b) + ' \u00b7 ' + fmtNum(e.total) + 'd';\n      btn.addEventListener('click', function () {\n        $('dateStart').value = e.a; $('dateEnd').value = e.b; recalc();\n        window.scrollTo({ top: 0, behavior: 'smooth' });\n      });\n      wrap.appendChild(btn);\n    });\n  }\n\n  /* ---------- milestone mode ---------- */\n  var msN = 10000;\n  function paintPreset() {\n    document.querySelectorAll('.msPreset').forEach(function (btn) {\n      var on = +btn.dataset.n === msN && !$('msCustom').value;\n      btn.classList.toggle('bg-terra', on);\n      btn.classList.toggle('text-white', on);\n      btn.classList.toggle('border-terra', on);\n      btn.classList.toggle('bg-white', !on);\n    });\n  }\n  function recalcMilestone() {\n    paintPreset();\n    var birth = $('msBirth').value;\n    var custom = parseInt($('msCustom').value, 10);\n    var n = isFinite(custom) && custom > 0 ? custom : msN;\n    if (!parseDate(birth)) {\n      $('msResult').classList.add('hidden');\n      $('msHint').classList.remove('hidden');\n      return;\n    }\n    var todayISO = msToISO(Date.now());\n    var mp = milestoneProgress(birth, n, todayISO);\n    $('msResult').classList.remove('hidden');\n    $('msHint').classList.add('hidden');\n    $('msBig').textContent = fmtNum(n) + ' days old';\n    $('msDate').textContent = formatLong(mp.target.date);\n    $('msDow').textContent = mp.target.dow + (mp.target.leapYear ? ' \u00b7 a leap year' : '');\n    $('msPct').textContent = mp.percent + '%';\n    $('msBar').style.width = mp.percent + '%';\n    $('msRemain').textContent = mp.passed\n      ? 'Already passed \u2014 that was ' + fmtNum(-mp.remainingDays) + ' days ago.'\n      : mp.remainingDays === 0\n        ? 'Today is the day \u2014 celebrate!'\n        : fmtNum(mp.remainingDays) + ' days to go (' + fmtNum(mp.livedDays) + ' lived so far).';\n  }\n  document.querySelectorAll('.msPreset').forEach(function (btn) {\n    btn.addEventListener('click', function () {\n      msN = +btn.dataset.n;\n      $('msCustom').value = '';\n      recalcMilestone();\n    });\n  });\n  $('msBirth').addEventListener('input', recalcMilestone);\n  $('msBirth').addEventListener('change', recalcMilestone);\n  $('msCustom').addEventListener('input', recalcMilestone);\n\n  /* ---------- date jumper ---------- */\n  var jDir = 1;\n  function recalcJumper() {\n    var base = $('jBase').value;\n    var n = parseInt($('jDays').value, 10);\n    if (!parseDate(base) || !isFinite(n)) {\n      $('jResult').classList.add('hidden');\n      $('jHint').classList.remove('hidden');\n      return;\n    }\n    var res = addDays(base, jDir * Math.abs(n));\n    $('jResult').classList.remove('hidden');\n    $('jHint').classList.add('hidden');\n    $('jDate').textContent = formatLong(res.date);\n    $('jDow').textContent = res.dow + (res.leapYear ? ' \u00b7 leap year' : '');\n  }\n  function paintJDir() {\n    $('jAdd').className = 'rounded-full px-5 py-2.5 text-sm font-bold ' + (jDir === 1 ? 'bg-terra text-white' : 'bg-white border border-linec text-ink');\n    $('jSub').className = 'rounded-full px-5 py-2.5 text-sm font-bold ' + (jDir === -1 ? 'bg-terra text-white' : 'bg-white border border-linec text-ink');\n    $('jAdd').setAttribute('aria-pressed', jDir === 1 ? 'true' : 'false');\n    $('jSub').setAttribute('aria-pressed', jDir === -1 ? 'true' : 'false');\n  }\n  $('jAdd').addEventListener('click', function () { jDir = 1; paintJDir(); recalcJumper(); });\n  $('jSub').addEventListener('click', function () { jDir = -1; paintJDir(); recalcJumper(); });\n  document.querySelectorAll('.jQuick').forEach(function (btn) {\n    btn.addEventListener('click', function () { $('jDays').value = btn.dataset.n; recalcJumper(); });\n  });\n  $('jBase').addEventListener('input', recalcJumper);\n  $('jBase').addEventListener('change', recalcJumper);\n  $('jDays').addEventListener('input', recalcJumper);\n\n  /* ---------- init ---------- */\n  renderRecent();\n  recalc();\n})();\n</script>\n</body>\n</html>\n";
